function checkout(){
javascript
// Create a plane geometry for the ground
const groundGeometry = new THREE.PlaneGeometry(5, 5);
const groundMaterial = new THREE.MeshStandardMaterial({
  color: 0x333333,
  roughness: 0.8,
  metalness: 0.2,
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Create a fire
const fireGeometry = new THREE.CircleGeometry(0.5, 32);
const fireMaterial = new THREE.MeshStandardMaterial({
  color: 0xff4500,
  emissive: 0xff2200,
  roughness: 0.5,
  metalness: 0.1,
  transparent: true,
  opacity: 0.8,
});
const fire = new THREE.Mesh(fireGeometry, fireMaterial);
fire.position.y = 0.01; // Slightly above the ground to prevent z-fighting
fire.rotation.x = -Math.PI / 2;
fire.castShadow = true;
scene.add(fire);

// Optional: Add a point light to simulate firelight
const fireLight = new THREE.PointLight(0xffaa33, 1, 5, 2);
fireLight.position.set(0, 0.5, 0);
fireLight.castShadow = true;
scene.add(fireLight);
setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
